fn supported_call(kind: CallKind, name: &str) -> SupportedCall {
    SupportedCall {
        kind,
        name: name.to_string(),
    }
}

fn signature(args: Vec<SupportedArg>) -> SupportedSignature {
    SupportedSignature {
        args: args.into_boxed_slice(),
    }
}

fn arg(ty: SupportedTy, argument_name: Option<&str>, has_default: bool) -> SupportedArg {
    SupportedArg {
        ty,
        argument_name: argument_name.map(str::to_string),
        has_default,
    }
}
